import re,os
files=["AlgebraicJacobian/Picard/FGAPicRepresentability.lean","AlgebraicJacobian/Picard/PicEtSubcanonical.lean","AlgebraicJacobian/Picard/PicEtSeparated.lean","AlgebraicJacobian/Picard/Pic0Et.lean","AlgebraicJacobian/Picard/PicEtDescentAssembly.lean","AlgebraicJacobian/Picard/Pic0EtTangentSpace.lean"]
for f in files:
    src=open(f).read().split("\n")
    # strip docstrings /- ... -/ and -- comments
    out=[];indoc=False
    for i,l in enumerate(src,1):
        s=l
        if indoc:
            if '-/' in s: indoc=False
            out.append((i,''));continue
        if re.search(r'/-',s) and '-/' not in s:
            indoc=True; out.append((i,''));continue
        if re.match(r'\s*/-.*-/\s*$',s): out.append((i,''));continue
        s=re.sub(r'--.*$','',s)
        out.append((i,s))
    txt=out
    # find class/structure decls and print the decl + following field lines
    for idx,(ln,s) in enumerate(txt):
        if re.match(r'^\s*(private |protected |noncomputable |scoped )*(class|structure)\s+\w',s):
            block=[]
            j=idx
            while j<len(txt):
                cur=txt[j][1]
                if j>idx and re.match(r'^\S',cur) and not re.match(r'^\s*(where|\|)',cur) and j>idx and cur.strip() and not re.match(r'^\s',cur):
                    # a new top-level line after the block started, and we've passed 'where'
                    if any('where' in b[1] for b in block) and not cur.startswith(' '):
                        break
                block.append(txt[j]); j+=1
                if j-idx>25: break
            print("="*70)
            print(f, "line", ln)
            for bl,bs in block:
                if bs.strip(): print(f"  {bl}: {bs}")
